"""V2.6 — request/response schemas for the investigation workflow API."""

from __future__ import annotations

from datetime import datetime, timezone

from pydantic import BaseModel, ConfigDict, field_validator

from backend.app.investigation.models import HistoryAction, InvestigationStatus

MAX_NOTE_LENGTH = 1000

# Shown with every investigation response so the framing travels with the data.
WORKFLOW_DISCLAIMER = (
    "Investigation status and notes are recorded by human investigators. "
    "They are not generated by NidhiGuard and do not alter the risk score."
)


def as_utc(value: datetime) -> datetime:
    """SQLite returns timezone-naive datetimes; ours are always stored as UTC. Make that explicit
    so clients (JavaScript Date) do not misread them as local time."""
    return value.replace(tzinfo=timezone.utc) if value.tzinfo is None else value.astimezone(timezone.utc)


class StatusChangeRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")

    status: InvestigationStatus


class NoteRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")

    note: str

    @field_validator("note")
    @classmethod
    def _clean_note(cls, value: str) -> str:
        value = value.strip()
        if not value:
            raise ValueError("Note must not be empty.")
        if len(value) > MAX_NOTE_LENGTH:
            raise ValueError(f"Note must be at most {MAX_NOTE_LENGTH} characters.")
        return value


class InvestigationHistoryEntry(BaseModel):
    id: int
    project_id: str
    action: HistoryAction
    previous_status: InvestigationStatus | None
    new_status: InvestigationStatus | None
    note: str | None
    username: str
    user_role: str
    created_at: datetime


class InvestigationResponse(BaseModel):
    """GET /api/projects/{id}/investigation — workflow state + audit trail (oldest first)."""

    project_id: str
    status: InvestigationStatus
    created_at: datetime | None  # None until the first workflow action
    updated_at: datetime | None
    history: list[InvestigationHistoryEntry]
    disclaimer: str = WORKFLOW_DISCLAIMER


class InvestigationSummary(BaseModel):
    project_id: str
    status: InvestigationStatus
    last_action_at: datetime | None


class InvestigationSummariesResponse(BaseModel):
    """GET /api/investigations — one row per project that has any workflow record (others are implicitly NEW)."""

    default_status: InvestigationStatus = InvestigationStatus.NEW
    items: list[InvestigationSummary]
